('KA-Python', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಮರುಬಳಕೆ ಮಾಡಬಹುದಾದ ಕೋಡ್ ಹೊಂದಿರುವ ಘಟಕವನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಮಾಡ್ಯೂಲ್', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪೈಥಾನ್ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಸಂಬಂಧಿತ ಮಾಡ್ಯೂಲ್‌ಗಳ ಗುಂಪನ್ನು ______ ಎಂದು ಕರೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'ಪ್ಯಾಕೇಜ್', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪೈಥಾನ್ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಕಾರ್ಯಕ್ರಮದ ತಪ್ಪುಗಳನ್ನು ಕಂಡುಹಿಡಿದು ಸರಿಪಡಿಸುವ ಪ್ರಕ್ರಿಯೆಯನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ದೋಷಶೋಧನೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪೈಥಾನ್ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಪೈಥಾನ್ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್ ಸರಳ ವಾಕ್ಯರಚನೆ ಹೊಂದಿರುವ ಉನ್ನತ ಮಟ್ಟದ ಪ್ರೋಗ್ರಾಮಿಂಗ್ ಭಾಷೆಯಾಗಿದ್ದು ವಿವಿಧ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಬಳಸಲಾಗುತ್ತದೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಚರ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಮೌಲ್ಯವನ್ನು ಹೆಸರಿನ ಮೂಲಕ ಸಂಗ್ರಹಿಸಲು ಬಳಸುವ ಗುರುತನ್ನು ಚರ ಎಂದು ಕರೆಯಬಹುದು.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ದತ್ತಾಂಶ ಪ್ರಕಾರ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಒಂದು ಮೌಲ್ಯ ಯಾವ ರೀತಿಯ ದತ್ತಾಂಶವನ್ನು ಪ್ರತಿನಿಧಿಸುತ್ತದೆ ಎಂಬುದನ್ನು ಸೂಚಿಸುವ ವರ್ಗೀಕರಣವೇ ದತ್ತಾಂಶ ಪ್ರಕಾರ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
