('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಪುನರಾವರ್ತನೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಒಂದು ಕಾರ್ಯವನ್ನು ನಿರ್ದಿಷ್ಟ ನಿಯಮದಂತೆ ಮತ್ತೆ ಮತ್ತೆ ನಡೆಸುವುದೇ ಪುನರಾವರ್ತನೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಕೋಡ್ ಮರುಬಳಕೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಈಗಾಗಲೇ ರಚಿಸಿದ ಕೋಡ್ ಅನ್ನು ಅಗತ್ಯವಿರುವ ಬೇರೆ ಭಾಗಗಳಲ್ಲಿಯೂ ಬಳಸುವುದೇ ಕೋಡ್ ಮರುಬಳಕೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಕಾರ್ಯಕ್ರಮ ಪರೀಕ್ಷೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಕ್ರಮದ ವಿವಿಧ ಭಾಗಗಳು ನಿರೀಕ್ಷೆಯಂತೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುವ ಪ್ರಕ್ರಿಯೆಯೇ ಕಾರ್ಯಕ್ರಮ ಪರೀಕ್ಷೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಇನ್‌ಪುಟ್ ಪರಿಶೀಲನೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಬಳಕೆದಾರರಿಂದ ಬಂದ ಮಾಹಿತಿಯ ಸ್ವರೂಪ ಮತ್ತು ಮಾನ್ಯತೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದೇ ಇನ್‌ಪುಟ್ ಪರಿಶೀಲನೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಪೈಥಾನ್‌ನ ಬಳಕೆ ಕ್ಷೇತ್ರಗಳನ್ನು ಹೆಸರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಣೆ, ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ, ಜಾಲ ಅನ್ವಯಿಕೆ, ಸ್ವಯಂಚಾಲನೆ ಮತ್ತು ವೈಜ್ಞಾನಿಕ ಗಣನೆಗಳಲ್ಲಿ ಪೈಥಾನ್ ಬಳಸಲಾಗುತ್ತದೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸುವ ಉತ್ತರ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಪೈಥಾನ್‌ನ ಪ್ರಮುಖ சிறப்பம்சங்களை ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್ ಸರಳ ಮತ್ತು ಓದಲು ಸುಲಭವಾದ ವಾಕ್ಯರಚನೆ ಹೊಂದಿದೆ. ಇದರಲ್ಲಿ ಅನೇಕ ಅಂತರ್ನಿರ್ಮಿತ ಸೌಲಭ್ಯಗಳಿದ್ದು ವಿವಿಧ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಬಳಸಬಹುದು. ಕಾರ್ಯ, ವರ್ಗ, ಮಾಡ್ಯೂಲ್ ಮತ್ತು ಪ್ಯಾಕೇಜ್‌ಗಳ ಮೂಲಕ ಕೋಡ್ ಅನ್ನು ಸಂಘಟಿಸಿ ಮರುಬಳಕೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಚರಗಳು ಮತ್ತು ದತ್ತಾಂಶ ಪ್ರಕಾರಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಚರವು ಮೌಲ್ಯವನ್ನು ಹೆಸರಿನ ಮೂಲಕ ಸಂಗ್ರಹಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಮೌಲ್ಯದ ಸ್ವರೂಪಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಪೂರ್ಣಾಂಕ, ತೇಲುವ ಬಿಂದು ಸಂಖ್ಯೆ, ಪಠ್ಯ ಮತ್ತು ಸತ್ಯಾಸತ್ಯತೆ ಮುಂತಾದ ದತ್ತಾಂಶ ಪ್ರಕಾರಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ. ಸರಿಯಾದ ಪ್ರಕಾರ ಆಯ್ಕೆ ಮಾಡಿದರೆ ದತ್ತಾಂಶವನ್ನು ಸರಿಯಾಗಿ ನಿರ್ವಹಿಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಪಟ್ಟಿ, ಟಪಲ್, ಸಮೂಹ ಮತ್ತು ನಿಘಂಟನ್ನು ಹೋಲಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪಟ್ಟಿ ಕ್ರಮಬದ್ಧ ಮತ್ತು ಬದಲಾಯಿಸಬಹುದಾದ ಸಂಗ್ರಹ. ಟಪಲ್ ಕ್ರಮಬದ್ಧ ಆದರೆ ಸಾಮಾನ್ಯವಾಗಿ ಬದಲಾಯಿಸಲಾಗದ ಸಂಗ್ರಹ. ಸಮೂಹ ಅದ್ವಿತೀಯ ಮೌಲ್ಯಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತದೆ. ನಿಘಂಟು ಕೀಲಿ ಮತ್ತು ಮೌಲ್ಯದ ಜೋಡಿಗಳನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ. ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಸೂಕ್ತ ರಚನೆಯನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಷರತ್ತು ಹೇಳಿಕೆಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಷರತ್ತು ಹೇಳಿಕೆಗಳು ನಿರ್ದಿಷ್ಟ ಪರಿಸ್ಥಿತಿಯ ಆಧಾರದ ಮೇಲೆ ಬೇರೆ ಬೇರೆ ಸೂಚನೆಗಳನ್ನು ಕಾರ್ಯಗತಗೊಳಿಸಲು ನೆರವಾಗುತ್ತವೆ. ಒಂದು ವೇಳೆ, ಇಲ್ಲದಿದ್ದರೆ ಮತ್ತು ಇಲ್ಲದಿದ್ದರೆ ಒಂದು ವೇಳೆ ಎಂಬ ರೂಪಗಳ ಮೂಲಕ ಹಲವು ಪರಿಸ್ಥಿತಿಗಳನ್ನು ನಿರ್ವಹಿಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಲೂಪ್‌ಗಳ ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಒಂದೇ ಕಾರ್ಯವನ್ನು ಪುನರಾವರ್ತಿಸಲು ಲೂಪ್‌ಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ. ಸಂಗ್ರಹದ ಪ್ರತಿಯೊಂದು ಅಂಶವನ್ನು ಪರಿಶೀಲಿಸಲು ಪ್ರತಿ-ಗಾಗಿ ಲೂಪ್ ಮತ್ತು ಷರತ್ತು ಸತ್ಯವಾಗಿರುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಲು ಯಾವಾಗ ಲೂಪ್ ಬಳಸಬಹುದು. ನಿಲ್ಲಿಸು ಮತ್ತು ಮುಂದುವರಿಸು ಸೂಚನೆಗಳಿಂದ ಪುನರಾವರ್ತನೆಯನ್ನು ನಿಯಂತ್ರಿಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಕಾರ್ಯಗಳ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಗಳು ದೊಡ್ಡ ಕಾರ್ಯಕ್ರಮವನ್ನು ಸಣ್ಣ, ಅರ್ಥಪೂರ್ಣ ಘಟಕಗಳಾಗಿ ವಿಭಜಿಸುತ್ತವೆ. ಒಂದೇ ಕೋಡ್ ಅನ್ನು ಹಲವು ಬಾರಿ ಬರೆಯುವ ಅಗತ್ಯ ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಪರೀಕ್ಷೆ, ನಿರ್ವಹಣೆ ಮತ್ತು ಮರುಬಳಕೆ ಸುಲಭವಾಗುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ವಾದಾಂಶ ಮತ್ತು ಹಿಂತಿರುಗುವ ಮೌಲ್ಯವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಕ್ಕೆ ಅಗತ್ಯವಿರುವ ಮಾಹಿತಿಯನ್ನು ವಾದಾಂಶಗಳ ಮೂಲಕ ನೀಡಬಹುದು. ಕಾರ್ಯವು ತನ್ನ ಕೆಲಸ ಪೂರ್ಣಗೊಳಿಸಿದ ನಂತರ ಹಿಂತಿರುಗುವ ಮೌಲ್ಯದ ಮೂಲಕ ಫಲಿತಾಂಶವನ್ನು ಹೊರಗೆ ನೀಡಬಹುದು. ಇದರಿಂದ ಕಾರ್ಯಗಳನ್ನು ಸಾಮಾನ್ಯ ಮತ್ತು ಮರುಬಳಕೆ ಮಾಡಬಹುದಾದ ರೀತಿಯಲ್ಲಿ ರೂಪಿಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ವರ್ಗ ಮತ್ತು ವಸ್ತುವಿನ ಪರಿಕಲ್ಪನೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವರ್ಗವು ವಸ್ತುಗಳ ಗುಣಲಕ್ಷಣ ಮತ್ತು ವಿಧಾನಗಳನ್ನು ವಿವರಿಸುವ ವಿನ್ಯಾಸ ರೂಪವಾಗಿದೆ. ಆ ವರ್ಗದ ಆಧಾರದ ಮೇಲೆ ರಚಿಸಲಾದ ನಿರ್ದಿಷ್ಟ ಘಟಕವನ್ನು ವಸ್ತು ಎಂದು ಕರೆಯಬಹುದು. ಈ ವಿಧಾನವು ದೊಡ್ಡ ಕಾರ್ಯಕ್ರಮಗಳನ್ನು ಸಂಘಟಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ವಿನಾಯಿತಿ ನಿರ್ವಹಣೆಯ ಅಗತ್ಯವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಕ್ರಮದ ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆಯಲ್ಲಿ ನಿರೀಕ್ಷಿಸದ ಪರಿಸ್ಥಿತಿಗಳು ಉಂಟಾಗಬಹುದು. ಅವುಗಳನ್ನು ಸೂಕ್ತವಾಗಿ ಹಿಡಿದು ಪರ್ಯಾಯ ಕ್ರಮ ಕೈಗೊಂಡರೆ ಕಾರ್ಯಕ್ರಮವು ಅನಗತ್ಯವಾಗಿ ನಿಲ್ಲುವುದನ್ನು ತಪ್ಪಿಸಬಹುದು. ಇದರಿಂದ ಬಳಕೆದಾರರಿಗೆ ಸ್ಪಷ್ಟ ಪ್ರತಿಕ್ರಿಯೆ ನೀಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಕಡತ ನಿರ್ವಹಣೆಯ ಹಂತಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮೊದಲು ಸೂಕ್ತ ಕಡತವನ್ನು ಸರಿಯಾದ ವಿಧಾನದಲ್ಲಿ ತೆರೆಯಬೇಕು. ನಂತರ ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಓದುವುದು ಅಥವಾ ಬರೆಯುವುದು ಮಾಡಬೇಕು. ಕೆಲಸ ಮುಗಿದ ನಂತರ ಕಡತವನ್ನು ಸರಿಯಾಗಿ ಮುಚ್ಚಬೇಕು. ದೋಷ ಸಾಧ್ಯತೆಗಳನ್ನೂ ಗಮನಿಸಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಇಂಡೆಂಟೇಶನ್‌ನ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್‌ನಲ್ಲಿ ಕೋಡ್ ಯಾವ ಗುಂಪಿಗೆ ಸೇರಿದೆ ಎಂಬುದನ್ನು ಇಂಡೆಂಟೇಶನ್ ಸೂಚಿಸುತ್ತದೆ. ಷರತ್ತು, ಲೂಪ್ ಮತ್ತು ಕಾರ್ಯಗಳ ಒಳಗಿನ ಸೂಚನೆಗಳನ್ನು ಸರಿಯಾದ ಮಟ್ಟದಲ್ಲಿ ಇರಿಸುವುದು ಅಗತ್ಯ. ತಪ್ಪಾದ ಇಂಡೆಂಟೇಶನ್ ವಾಕ್ಯರಚನಾ ಸಮಸ್ಯೆಗೆ ಕಾರಣವಾಗಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮಾಡ್ಯೂಲ್ ಮತ್ತು ಪ್ಯಾಕೇಜ್‌ಗಳ ಉಪಯೋಗವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಾಡ್ಯೂಲ್ ಮೂಲಕ ಸಂಬಂಧಿತ ಕೋಡ್ ಅನ್ನು ಪ್ರತ್ಯೇಕ ಕಡತದಲ್ಲಿ ಇಟ್ಟು ಮರುಬಳಕೆ ಮಾಡಬಹುದು. ಹಲವು ಸಂಬಂಧಿತ ಮಾಡ್ಯೂಲ್‌ಗಳನ್ನು ಪ್ಯಾಕೇಜ್‌ನಲ್ಲಿ ಸಂಘಟಿಸಬಹುದು. ಇದರಿಂದ ದೊಡ್ಡ ಕಾರ್ಯಕ್ರಮವನ್ನು ನಿರ್ವಹಿಸುವುದು ಮತ್ತು ತಂಡದಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳುವುದು ಸುಲಭವಾಗುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಪಠ್ಯ ಸಂಸ್ಕರಣೆಯ ಸಾಮಾನ್ಯ ಕಾರ್ಯಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪಠ್ಯದ ಉದ್ದ ಕಂಡುಹಿಡಿಯುವುದು, ಭಾಗಗಳಾಗಿ ವಿಭಜಿಸುವುದು, ಎರಡು ಪಠ್ಯಗಳನ್ನು ಜೋಡಿಸುವುದು ಮತ್ತು ನಿರ್ದಿಷ್ಟ ಅಂಶ ಹುಡುಕುವುದು ಸಾಮಾನ್ಯ ಕಾರ್ಯಗಳು. ಪಠ್ಯ ಆಧಾರಿತ ಮಾಹಿತಿಯನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಲು ಮತ್ತು ವಿಶ್ಲೇಷಿಸಲು ಇವು ಉಪಯುಕ್ತ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಪಟ್ಟಿ ವಿಧಾನಗಳ ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪಟ್ಟಿಗೆ ಅಂಶ ಸೇರಿಸಲು ಸೇರಿಸು ವಿಧಾನ, ಅಂಶ ತೆಗೆದುಹಾಕಲು ತೆಗೆದುಹಾಕು ವಿಧಾನ, ಅಂಶಗಳನ್ನು ಕ್ರಮಬದ್ಧಗೊಳಿಸಲು ವಿಂಗಡಿಸು ವಿಧಾನ ಮತ್ತು ನಿರ್ದಿಷ್ಟ ಅಂಶದ ಪುನರಾವರ್ತನೆ ತಿಳಿಯಲು ಎಣಿಸು ವಿಧಾನ ಬಳಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ದೋಷಶೋಧನೆಯ ಪ್ರಕ್ರಿಯೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮೊದಲು ದೋಷ ಸಂದೇಶ ಮತ್ತು ಅದರ ಸ್ಥಳವನ್ನು ಗಮನಿಸಬೇಕು. ನಂತರ ಸಮಸ್ಯೆಯನ್ನು ಸಣ್ಣ ಭಾಗಕ್ಕೆ ವಿಭಜಿಸಿ ಪರೀಕ್ಷಿಸಬೇಕು. ಬಳಸಿದ ಮೌಲ್ಯಗಳು, ಷರತ್ತುಗಳು ಮತ್ತು ಕಾರ್ಯಗಳ ಕ್ರಮ ಪರಿಶೀಲಿಸಿ ಮೂಲ ಕಾರಣ ಕಂಡುಹಿಡಿದು ತಿದ್ದುಪಡಿ ಮಾಡಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ವಾಕ್ಯರಚನಾ, ಕಾರ್ಯಗತ ಮತ್ತು ತಾರ್ಕಿಕ ದೋಷಗಳನ್ನು ಹೋಲಿಸಿ.', NULL, NULL, NULL, NULL, 'ವಾಕ್ಯರಚನಾ ದೋಷವು ಭಾಷೆಯ ನಿಯಮ ಉಲ್ಲಂಘನೆಯಿಂದ ಉಂಟಾಗುತ್ತದೆ. ಕಾರ್ಯಗತ ದೋಷವು ಕಾರ್ಯಕ್ರಮ ನಡೆಯುವಾಗ ಉಂಟಾಗುವ ಅಸಾಮಾನ್ಯ ಸ್ಥಿತಿಗೆ ಸಂಬಂಧಿಸಿದೆ. ತಾರ್ಕಿಕ ದೋಷದಲ್ಲಿ ಕಾರ್ಯಕ್ರಮ ನಡೆಯುತ್ತದೆ ಆದರೆ ತರ್ಕ ತಪ್ಪಿರುವುದರಿಂದ ಫಲಿತಾಂಶ ತಪ್ಪಾಗುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಕಾರ್ಯಕ್ರಮ ಪರೀಕ್ಷೆಯ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಕ್ರಮದ ಪ್ರತಿಯೊಂದು ಪ್ರಮುಖ ಭಾಗವು ನಿರೀಕ್ಷೆಯಂತೆ ಕೆಲಸ ಮಾಡುತ್ತದೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸುವುದು ಅಗತ್ಯ. ಸಾಮಾನ್ಯ, ಅಂಚಿನ ಮತ್ತು ತಪ್ಪಾದ ಇನ್‌ಪುಟ್‌ಗಳನ್ನು ಬಳಸಿ ಪರೀಕ್ಷಿಸಿದರೆ ದೋಷಗಳನ್ನು ಮೊದಲೇ ಕಂಡುಹಿಡಿಯಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಕೋಡ್ ಮರುಬಳಕೆಯ ಪ್ರಯೋಜನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಒಮ್ಮೆ ಬರೆಯಲಾದ ವಿಶ್ವಾಸಾರ್ಹ ಕೋಡ್ ಅನ್ನು ಅಗತ್ಯವಿರುವ ಹಲವು ಸ್ಥಳಗಳಲ್ಲಿ ಬಳಸಬಹುದು. ಇದರಿಂದ ಸಮಯ ಉಳಿಯುತ್ತದೆ, ನಕಲು ಕೋಡ್ ಕಡಿಮೆಯಾಗುತ್ತದೆ ಮತ್ತು ನಿರ್ವಹಣೆ ಸುಲಭವಾಗುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಪೈಥಾನ್‌ನ ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಣಾ ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್ ಅನ್ನು ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ, ಶುದ್ಧೀಕರಣ, ಪರಿವರ್ತನೆ, ಗಣನೆ ಮತ್ತು ದೃಶ್ಯೀಕರಣಕ್ಕಾಗಿ ಬಳಸಬಹುದು. ದೊಡ್ಡ ಪ್ರಮಾಣದ ದತ್ತಾಂಶವನ್ನು ಸಂಸ್ಕರಿಸಲು ವಿವಿಧ ಗ್ರಂಥಾಲಯಗಳ ನೆರವು ಪಡೆಯಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಪೈಥಾನ್‌ನ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಕ್ಷೇತ್ರದ ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್ ಅನ್ನು ದತ್ತಾಂಶ ಸಿದ್ಧತೆ, ಮಾದರಿ ತರಬೇತಿ, ಫಲಿತಾಂಶ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಬುದ್ಧಿವಂತ ಅನ್ವಯಿಕೆಗಳ ಅಭಿವೃದ್ಧಿಯಲ್ಲಿ ಬಳಸಬಹುದು. ಸರಳ ವಾಕ್ಯರಚನೆ ಮತ್ತು ವ್ಯಾಪಕ ಗ್ರಂಥಾಲಯ ಬೆಂಬಲದಿಂದ ಇದು ಈ ಕ್ಷೇತ್ರದಲ್ಲಿ ಉಪಯುಕ್ತವಾಗಿದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಸ್ವಯಂಚಾಲನೆಗಾಗಿ ಪೈಥಾನ್ ಹೇಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ?', NULL, NULL, NULL, NULL, 'ಪುನರಾವರ್ತಿತ ಕೆಲಸಗಳನ್ನು ಸೂಚನೆಗಳ ರೂಪದಲ್ಲಿ ಬರೆಯಬಹುದು. ಕಡತ ನಿರ್ವಹಣೆ, ದತ್ತಾಂಶ ಸಂಸ್ಕರಣೆ ಮತ್ತು ನಿಯಮಿತ ಕಾರ್ಯಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತಗೊಳಿಸುವ ಮೂಲಕ ಸಮಯ ಮತ್ತು ಮಾನವ ಪ್ರಯತ್ನ ಕಡಿಮೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪೈಥಾನ್ ಕಾರ್ಯಕ್ರಮವನ್ನು ಉತ್ತಮವಾಗಿ ಸಂಘಟಿಸುವ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸಂಬಂಧಿತ ಕಾರ್ಯಗಳನ್ನು ಪ್ರತ್ಯೇಕ ಕಾರ್ಯಗಳಲ್ಲಿ, ಸಂಬಂಧಿತ ಗುಣಲಕ್ಷಣಗಳನ್ನು ವರ್ಗಗಳಲ್ಲಿ ಮತ್ತು ಮರುಬಳಕೆ ಮಾಡಬಹುದಾದ ಕೋಡ್ ಅನ್ನು ಮಾಡ್ಯೂಲ್‌ಗಳಲ್ಲಿ ಇಡಬೇಕು. ಅರ್ಥಪೂರ್ಣ ಹೆಸರು, ಸರಿಯಾದ ಇಂಡೆಂಟೇಶನ್ ಮತ್ತು ಅಗತ್ಯ ಟಿಪ್ಪಣಿಗಳನ್ನು ಬಳಸಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಇನ್‌ಪುಟ್ ಪರಿಶೀಲನೆಯ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಬಳಕೆದಾರರಿಂದ ಬಂದ ಮಾಹಿತಿ ನಿರೀಕ್ಷಿತ ಸ್ವರೂಪದಲ್ಲಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುವುದು ಅಗತ್ಯ. ತಪ್ಪಾದ ಅಥವಾ ಅಪಾಯಕಾರಿ ಇನ್‌ಪುಟ್ ಅನ್ನು ಸರಿಯಾಗಿ ನಿರ್ವಹಿಸಿದರೆ ಕಾರ್ಯಕ್ರಮದ ವಿಶ್ವಾಸಾರ್ಹತೆ ಹೆಚ್ಚುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ದತ್ತಾಂಶ ರಚನೆ ಆಯ್ಕೆ ಮಾಡುವ ವಿಧಾನವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶವನ್ನು ಹೇಗೆ ಸಂಗ್ರಹಿಸಬೇಕು ಮತ್ತು ಯಾವ ಕಾರ್ಯಗಳನ್ನು ಹೆಚ್ಚಾಗಿ ಮಾಡಬೇಕು ಎಂಬುದನ್ನು ಮೊದಲು ನಿರ್ಧರಿಸಬೇಕು. ಕ್ರಮಬದ್ಧ ಬದಲಾಯಿಸಬಹುದಾದ ಸಂಗ್ರಹಕ್ಕೆ ಪಟ್ಟಿ, ಸ್ಥಿರ ಕ್ರಮಬದ್ಧ ಸಂಗ್ರಹಕ್ಕೆ ಟಪಲ್, ಅದ್ವಿತೀಯ ಮೌಲ್ಯಗಳಿಗೆ ಸಮೂಹ ಮತ್ತು ಕೀಲಿ-ಮೌಲ್ಯ ಸಂಬಂಧಕ್ಕೆ ನಿಘಂಟು ಸೂಕ್ತವಾಗಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಕಾರ್ಯ ಮತ್ತು ವರ್ಗದ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯವು ನಿರ್ದಿಷ್ಟ ಕೆಲಸವನ್ನು ನಿರ್ವಹಿಸುವ ಸೂಚನೆಗಳ ಗುಂಪು. ವರ್ಗವು ಸಂಬಂಧಿತ ಗುಣಲಕ್ಷಣ ಮತ್ತು ವಿಧಾನಗಳನ್ನು ಹೊಂದಿರುವ ವಸ್ತುಗಳನ್ನು ರಚಿಸಲು ವಿನ್ಯಾಸ ರೂಪ. ಕಾರ್ಯಕ್ರಮದ ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಎರಡನ್ನೂ ಬಳಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಲೂಪ್ ನಿಯಂತ್ರಣ ಸೂಚನೆಗಳ ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ನಿಲ್ಲಿಸು ಸೂಚನೆಯು ಲೂಪ್ ಅನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ನಿಲ್ಲಿಸುತ್ತದೆ. ಮುಂದುವರಿಸು ಸೂಚನೆಯು ಪ್ರಸ್ತುತ ಪುನರಾವರ್ತನೆಯ ಉಳಿದ ಭಾಗವನ್ನು ಬಿಟ್ಟು ಮುಂದಿನ ಪುನರಾವರ್ತನೆಗೆ ಹೋಗುತ್ತದೆ. ಇವು ಸಂಕೀರ್ಣ ಪುನರಾವರ್ತನೆಗಳನ್ನು ನಿಯಂತ್ರಿಸಲು ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪೈಥಾನ್ ಕಲಿಯಲು ಮೂಲಭೂತ ಅಧ್ಯಯನ ಕ್ರಮವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮೊದಲು ಚರಗಳು, ದತ್ತಾಂಶ ಪ್ರಕಾರಗಳು ಮತ್ತು ಮೂಲಭೂತ ಕಾರ್ಯಗಳನ್ನು ಕಲಿಯಬೇಕು. ನಂತರ ಷರತ್ತುಗಳು, ಲೂಪ್‌ಗಳು, ಸಂಗ್ರಹಗಳು ಮತ್ತು ಕಾರ್ಯಗಳನ್ನು ಅಭ್ಯಾಸ ಮಾಡಬೇಕು. ಮುಂದೆ ವರ್ಗ, ಕಡತ ನಿರ್ವಹಣೆ, ವಿನಾಯಿತಿ ನಿರ್ವಹಣೆ ಮತ್ತು ಸಣ್ಣ ಯೋಜನೆಗಳ ಮೂಲಕ ಜ್ಞಾನವನ್ನು ಬಲಪಡಿಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ದೊಡ್ಡ ಪೈಥಾನ್ ಕಾರ್ಯಕ್ರಮವನ್ನು ನಿರ್ವಹಿಸುವ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಗಳನ್ನು ಸಣ್ಣ ಘಟಕಗಳಾಗಿ ವಿಭಜಿಸಿ, ಸಂಬಂಧಿತ ಕೋಡ್ ಅನ್ನು ಮಾಡ್ಯೂಲ್ ಮತ್ತು ಪ್ಯಾಕೇಜ್‌ಗಳಲ್ಲಿ ಸಂಘಟಿಸಬೇಕು. ಸ್ಪಷ್ಟ ಹೆಸರುಗಳು, ಸರಿಯಾದ ಇಂಡೆಂಟೇಶನ್, ಪರೀಕ್ಷೆಗಳು ಮತ್ತು ಅಗತ್ಯ ಟಿಪ್ಪಣಿಗಳನ್ನು ಬಳಸಬೇಕು. ದೋಷಶೋಧನೆ ಮತ್ತು ನಿಯಮಿತ ಪರಿಶೀಲನೆಯಿಂದ ಗುಣಮಟ್ಟ ಕಾಪಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪೈಥಾನ್‌ನ ಪ್ರಯೋಜನಗಳು ಮತ್ತು ಮಿತಿಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸರಳ ವಾಕ್ಯರಚನೆ, ವ್ಯಾಪಕ ಗ್ರಂಥಾಲಯ ಬೆಂಬಲ, ಮರುಬಳಕೆ ಮತ್ತು ವಿವಿಧ ಕ್ಷೇತ್ರಗಳ ಬಳಕೆ ಪ್ರಮುಖ ಪ್ರಯೋಜನಗಳು. ಕೆಲವು ಸಂದರ್ಭಗಳಲ್ಲಿ ಕಾರ್ಯಗತಗೊಳಿಸುವ ವೇಗ, ಸಂಪನ್ಮೂಲ ಬಳಕೆ ಅಥವಾ ನಿರ್ದಿಷ್ಟ ವ್ಯವಸ್ಥಾ ಮಟ್ಟದ ಅಗತ್ಯಗಳು ಮಿತಿಯಾಗಬಹುದು. ಆದ್ದರಿಂದ ಯೋಜನೆಯ ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಭಾಷೆಯನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಬಹು ಆಯ್ಕೆ', 'ಸುಲಭ', '2', 'ಪೈಥಾನ್‌ನ ಪ್ರಮುಖ ಲಕ್ಷಣಗಳಲ್ಲಿ ಯಾವವು ಸೇರಿವೆ? (ಹೆಚ್ಚುವರಿ ಪ್ರಶ್ನೆ 35)', 'ಸರಳ ವಾಕ್ಯರಚನೆ', 'ವ್ಯಾಪಕ ಅಂತರ್ನಿರ್ಮಿತ ಸೌಲಭ್ಯಗಳು', 'ವಿವಿಧ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಬಳಕೆ', 'ಮರುಬಳಕೆ ಮಾಡಬಹುದಾದ ಕೋಡ್', 'ಆಯ್ಕೆ ಅ, ಆಯ್ಕೆ ಆ, ಆಯ್ಕೆ ಇ, ಆಯ್ಕೆ ಈ', 'ನಾಲ್ಕೂ ಆಯ್ಕೆಗಳು ಪ್ರಶ್ನೆಯಲ್ಲಿ ಕೇಳಿದ ಪರಿಕಲ್ಪನೆಗೆ ಸಂಬಂಧಿಸಿದ ಸರಿಯಾದ ಅಂಶಗಳಾಗಿವೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ಸರಿ ಅಥವಾ ತಪ್ಪು', 'ಸುಲಭ', '1', 'ಪೈಥಾನ್ ಉನ್ನತ ಮಟ್ಟದ ಪ್ರೋಗ್ರಾಮಿಂಗ್ ಭಾಷೆಯಾಗಿದೆ. (ಹೆಚ್ಚುವರಿ ಪ್ರಶ್ನೆ 35)', 'ಸರಿ', 'ತಪ್ಪು', NULL, NULL, 'ಸರಿ', 'ಹೇಳಿಕೆಯು ಪೈಥಾನ್‌ನ ಮೂಲಭೂತ ಪರಿಕಲ್ಪನೆಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗಿದೆಯೇ ಎಂಬುದನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿದೆ.'),
('KA-Python', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಪೈಥಾನ್‌ನ ಪ್ರಮುಖ சிறப்பம்சங்களை ವಿವರಿಸಿ. (ಹೆಚ್ಚುವರಿ ಪ್ರಶ್ನೆ 30)', NULL, NULL, NULL, NULL, 'ಪೈಥಾನ್ ಸರಳ ಮತ್ತು ಓದಲು ಸುಲಭವಾದ ವಾಕ್ಯರಚನೆ ಹೊಂದಿದೆ. ಇದರಲ್ಲಿ ಅನೇಕ ಅಂತರ್ನಿರ್ಮಿತ ಸೌಲಭ್ಯಗಳಿದ್ದು ವಿವಿಧ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಬಳಸಬಹುದು. ಕಾರ್ಯ, ವರ್ಗ, ಮಾಡ್ಯೂಲ್ ಮತ್ತು ಪ್ಯಾಕೇಜ್‌ಗಳ ಮೂಲಕ ಕೋಡ್ ಅನ್ನು ಸಂಘಟಿಸಿ ಮರುಬಳಕೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ ಮತ್ತು ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.');